import { tv } from "tailwind-variants";

const toggleGroup = tv({
  base: [
    "flex items-center gap-2 rounded-lg border border-border p-1",
    "*:data-slot:border-none *:data-slot:shadow-none",
    "*:data-slot:focus-visible:z-1",
  ],
});

export { toggleGroup };

"use client";

import { useDirection } from "@base-ui/react";
import { ToggleGroup as BaseToggleGroup } from "@base-ui/react/toggle-group";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { toggleGroup } from "./toggle-group.style";

function ToggleGroup({ className, ...props }: BaseToggleGroup.Props) {
  const direction = useDirection();

  return (
    <BaseToggleGroup
      data-slot="toggle-group"
      className={mergeSlotClassName(toggleGroup, className)}
      {...props}
      dir={direction}
    />
  );
}

export { ToggleGroup };
